#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

# Spec 0004, issue #70: everything Shopper accounts need set up by hand.
# Run from the repository root:  bash scripts/setup-accounts.sh
# The Resend API key and Google client secret are pasted straight into
# Supabase and never saved here. Public values go to web/.env.local (for
# local dev) and to GitHub repository variables (for the deploy).

TOTAL_STAGES=10
ENV_FILE="web/.env.local"

banner "Amara's Pick: Shopper accounts set-up"

stage "Resend: account and domain"
say "Resend sends the sign-in emails from amaraspick.com. The free plan is enough."
open_url "https://resend.com/signup"
step "Sign up (or log in) with the email you use for Amara's Pick."
step "Left menu: Domains → Add domain."
step "Name: amaraspick.com   Region: Ireland (eu-west-1)   → Add."
note "Resend now shows 3 DNS records (MX and TXT on 'send', TXT on 'resend._domainkey')."
note "If it offers 'Sign in to Cloudflare' / auto-configure, use it, verify, and skip the next stage."
pause "Press Enter once the domain page with the DNS records is open."

stage "Cloudflare: add Resend's DNS records"
say "Copy each record from Resend into Cloudflare. They only touch the 'send' subdomain,"
say "so they don't affect the website or any email forwarding on amaraspick.com."
open_url "https://dash.cloudflare.com/?to=/:account/amaraspick.com/dns/records"
step "DNS → Records → Add record, once per row Resend shows."
step "Copy Type, Name and Content exactly. For MX, set the Priority Resend gives."
step "Leave Proxy status off (DNS only) where Cloudflare offers it. TTL: Auto."
step "Back in Resend, click 'Verify DNS Records'. It can take a few minutes."
until confirm "Does Resend show the domain as Verified?"; do
  note "Still pending is normal for a few minutes. Check each record matches, then try again."
done

stage "Resend: sending key"
open_url "https://resend.com/api-keys"
step "Create API key. Name: supabase-auth   Permission: Sending access   Domain: amaraspick.com."
step "Copy the key (starts re_). Resend shows it only once."
note "Keep it in your clipboard: you paste it into Supabase in the next stage. It is not saved here."
pause "Press Enter once the key is copied."

stage "Supabase: send sign-in emails through Resend"
ask SUPABASE_PROJECT_REF "Your Supabase project ref (the part after /project/ in the dashboard address):"
open_url "https://supabase.com/dashboard/project/${SUPABASE_PROJECT_REF}/auth/smtp"
step "Turn on 'Enable custom SMTP' and fill in:"
note "   Sender email: hello@amaraspick.com      Sender name: Amara's Pick"
note "   Host: smtp.resend.com   Port: 465   Username: resend   Password: the re_ key"
step "Save changes."
pause "Press Enter once saved."

stage "Supabase: site address and sign-in links"
open_url "https://supabase.com/dashboard/project/${SUPABASE_PROJECT_REF}/auth/url-configuration"
step "Site URL: https://amaraspick.com   → Save."
step "Redirect URLs → Add URL, one at a time:"
note "   https://amaraspick.com/**"
note "   https://www.amaraspick.com/**"
note "   http://localhost:5173/**"
open_url "https://supabase.com/dashboard/project/${SUPABASE_PROJECT_REF}/auth/providers"
step "Sign In / Providers → Email: keep it on, and set the email OTP / link expiry to 3600 seconds (1 hour). Save."
note "Leave 'Allow new users to sign up' on: the first sign-in makes the account (spec rule 3)."
pause "Press Enter once both pages are saved."

stage "Google: sign-in app"
say "Google needs an app so shoppers can 'Continue with Google'. It's free."
open_url "https://console.cloud.google.com/projectcreate"
step "Create a project called Amaras Pick, and make sure it's selected at the top."
open_url "https://console.cloud.google.com/auth/branding"
step "Google Auth Platform → Get started. App name: Amara's Pick. Support email: yours."
step "Audience: External. Contact email: yours. Agree and Create."
step "Branding: home page https://amaraspick.com, privacy policy https://amaraspick.com/privacy,"
step "terms https://amaraspick.com/terms, authorised domains amaraspick.com and supabase.co. Save."
open_url "https://console.cloud.google.com/auth/audience"
step "Audience → Publish app (so anyone can sign in, not only test users)."
pause "Press Enter once the app is published."

stage "Google: web client, connected to Supabase"
open_url "https://supabase.com/dashboard/project/${SUPABASE_PROJECT_REF}/auth/providers"
step "In Supabase, open Google under Sign In / Providers and copy its Callback URL."
note "It looks like https://${SUPABASE_PROJECT_REF}.supabase.co/auth/v1/callback"
open_url "https://console.cloud.google.com/auth/clients/create"
step "Application type: Web application. Name: Amara's Pick website."
step "Authorised JavaScript origins: https://amaraspick.com and http://localhost:5173"
step "Authorised redirect URIs: the Supabase Callback URL. → Create."
step "Copy the Client ID and Client secret into Supabase's Google provider, turn it on, Save."
note "The secret lives only in Supabase; this wizard does not save it."
pause "Press Enter once Google is enabled in Supabase."

stage "Supabase: public address and browser key"
say "These two are public by design (the browser uses them); row-level security keeps data safe."
open_url "https://supabase.com/dashboard/project/${SUPABASE_PROJECT_REF}/settings/api-keys"
step "Copy the Publishable key (starts sb_publishable_). Never the secret / service_role key."
ask SUPABASE_PUBLISHABLE_KEY "Paste the publishable key:"
SUPABASE_URL="https://${SUPABASE_PROJECT_REF}.supabase.co"
if [[ "$SUPABASE_PUBLISHABLE_KEY" == sb_secret_* ]]; then
  warn "That's a secret key. Copy the publishable one instead and run this stage again."
  exit 1
fi
write_env VITE_SUPABASE_URL "$SUPABASE_URL"
write_env VITE_SUPABASE_PUBLISHABLE_KEY "$SUPABASE_PUBLISHABLE_KEY"
set_var AMARAS_PICK_SUPABASE_URL "$SUPABASE_URL"
set_var AMARAS_PICK_SUPABASE_PUBLISHABLE_KEY "$SUPABASE_PUBLISHABLE_KEY"
note "If gh isn't set up, add both as repository variables at:"
note "https://github.com/Tico26/Yxra/settings/variables/actions"
pause

stage "Supabase: let the browser reach Shopper accounts"
say "Saved items and sizes live in the 'shoppers' schema, which the deploy creates"
say "once the database ticket (#71) is merged. The browser key must be allowed to reach it."
open_url "https://supabase.com/dashboard/project/${SUPABASE_PROJECT_REF}/settings/api"
step "Data API → Exposed schemas: add 'shoppers'. Save."
note "Not in the list yet? #71 isn't deployed. Skip this and come back to it later."
if ! confirm "Is 'shoppers' now in Exposed schemas?"; then
  SKIPPED+=("Add 'shoppers' to Supabase → Settings → Data API → Exposed schemas after #71 deploys")
fi

stage "Test: a sign-in email arrives"
open_url "https://supabase.com/dashboard/project/${SUPABASE_PROJECT_REF}/auth/users"
step "Add user → Send invitation, to your own email."
step "Check your inbox (and spam): it should come from hello@amaraspick.com."
if confirm "Did the email arrive from amaraspick.com?"; then
  say "Done. Tell Claude in the 'Add a login page' thread, and #70 can close."
  note "You can delete that test user from the Users list afterwards."
else
  SKIPPED+=("Test email did not arrive: check Resend → Logs, and the SMTP stage")
fi

finish
